class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        vistos = set()
        izq = 0
        mejor = 0
        for der, c in enumerate(s):
            # Encogemos por la izquierda hasta que `c` ya no se repita
            while c in vistos:
                vistos.remove(s[izq])
                izq += 1
            vistos.add(c)
            mejor = max(mejor, der - izq + 1)
        return mejor
